package android.media;
import org.padtv.bridge.MediaNative;
import java.nio.ByteBuffer;
import java.io.IOException;
import java.util.*;
public final class MediaExtractor {
 public static final int SAMPLE_FLAG_SYNC=1,SAMPLE_FLAG_ENCRYPTED=2,SAMPLE_FLAG_PARTIAL_FRAME=4,SEEK_TO_PREVIOUS_SYNC=0,SEEK_TO_NEXT_SYNC=1,SEEK_TO_CLOSEST_SYNC=2;
 private long handle;private final Set<Integer> selected=new HashSet<Integer>();private final Map<Integer,Integer> nalLengths=new HashMap<Integer,Integer>();private boolean current,eof;private long[] info;private byte[] sampleData;
 public MediaExtractor(){}
 public void setDataSource(String path)throws IOException{if(handle!=0)throw new IllegalStateException("Already opened");handle=MediaNative.open(path);}
 public void setDataSource(String path,Map<String,String> headers)throws IOException{if(headers!=null&&!headers.isEmpty())throw new UnsupportedOperationException("Custom media HTTP headers are not implemented");setDataSource(path);}
 public void setDataSource(android.content.Context c,android.net.Uri uri,Map<String,String> headers)throws IOException{setDataSource(uri.toString(),headers);}
 private void ready(){if(handle==0)throw new IllegalStateException("Extractor is not opened");}
 public int getTrackCount(){ready();return MediaNative.trackCount(handle);}
 public MediaFormat getTrackFormat(int track){ready();String[] a=MediaNative.trackFormat(handle,track);MediaFormat f=new MediaFormat();f.setString(MediaFormat.KEY_MIME,a[0]);if(a[0].startsWith("video/")){f.setInteger("width",Integer.parseInt(a[1]));f.setInteger("height",Integer.parseInt(a[2]));}else if(a[0].startsWith("audio/")){f.setInteger("sample-rate",Integer.parseInt(a[3]));f.setInteger("channel-count",Integer.parseInt(a[4]));}f.setLong("durationUs",Long.parseLong(a[5]));f.setInteger("max-input-size",4*1024*1024);byte[] extra=MediaNative.extra(handle,track);nalLengths.put(track,0);if(extra.length>0){if(a[0].equals("video/avc")&&extra[0]==1){avc(f,extra);nalLengths.put(track,(extra[4]&3)+1);}else if(a[0].equals("video/hevc")&&extra[0]==1){hevc(f,extra);nalLengths.put(track,(extra[21]&3)+1);}else f.setByteBuffer("csd-0",ByteBuffer.wrap(extra));}return f;}
 private static void hevc(MediaFormat f,byte[] b){if(b.length<23)throw new IllegalArgumentException("Invalid HEVC config");int arrays=b[22]&255,pos=23;java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();for(int j=0;j<arrays;j++){if(pos+3>b.length)throw new IllegalArgumentException();pos++;int count=((b[pos]&255)<<8)|(b[pos+1]&255);pos+=2;for(int i=0;i<count;i++){if(pos+2>b.length)throw new IllegalArgumentException();int n=((b[pos]&255)<<8)|(b[pos+1]&255);pos+=2;if(n>b.length-pos)throw new IllegalArgumentException();out.write(new byte[]{0,0,0,1},0,4);out.write(b,pos,n);pos+=n;}}f.setByteBuffer("csd-0",ByteBuffer.wrap(out.toByteArray()));}
 private static void avc(MediaFormat f,byte[] b){try{int pos=5;int count=b[pos++]&31;java.io.ByteArrayOutputStream sps=new java.io.ByteArrayOutputStream(),pps=new java.io.ByteArrayOutputStream();for(int group=0;group<2;group++){for(int i=0;i<count;i++){int n=((b[pos]&255)<<8)|(b[pos+1]&255);pos+=2;if(n>b.length-pos)throw new IllegalArgumentException();java.io.ByteArrayOutputStream out=group==0?sps:pps;out.write(new byte[]{0,0,0,1},0,4);out.write(b,pos,n);pos+=n;}if(group==0)count=b[pos++]&255;}f.setByteBuffer("csd-0",ByteBuffer.wrap(sps.toByteArray()));f.setByteBuffer("csd-1",ByteBuffer.wrap(pps.toByteArray()));}catch(IndexOutOfBoundsException e){throw new IllegalArgumentException("Invalid AVC configuration",e);}}
 public void selectTrack(int track){if(track<0||track>=getTrackCount())throw new IllegalArgumentException("Invalid track");selected.add(track);}
 public void unselectTrack(int track){selected.remove(track);if(current&&info[0]==track){current=false;sampleData=null;}}
 private boolean sample(){ready();if(current)return true;if(eof||selected.isEmpty())return false;try{while(MediaNative.next(handle)){info=MediaNative.packetInfo(handle);if(selected.contains((int)info[0])){current=true;return true;}}eof=true;return false;}catch(IOException e){throw new IllegalStateException("Demux failed",e);}}
 private byte[] data(){if(sampleData!=null)return sampleData;byte[] b=MediaNative.packet(handle);int track=(int)info[0];if(!nalLengths.containsKey(track))getTrackFormat(track);int size=nalLengths.get(track);if(size==0)return sampleData=b;java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int pos=0;while(pos<b.length){if(pos+size>b.length)throw new IllegalArgumentException("Truncated NAL length");long n=0;for(int i=0;i<size;i++)n=(n<<8)|(b[pos++]&255);if(n<=0||n>b.length-pos||out.size()+n+4>32*1024*1024)throw new IllegalArgumentException("Invalid NAL sample");out.write(new byte[]{0,0,0,1},0,4);out.write(b,pos,(int)n);pos+=(int)n;}return sampleData=out.toByteArray();}
 public int readSampleData(ByteBuffer buffer,int offset){if(!sample())return -1;byte[] b=data();if(offset<0||offset>buffer.capacity()-b.length)throw new IllegalArgumentException("Sample exceeds buffer");ByteBuffer out=buffer.duplicate();out.clear();out.position(offset);out.put(b);return b.length;}
 public long getSampleTime(){return sample()?info[1]:-1;}public int getSampleTrackIndex(){return sample()?(int)info[0]:-1;}public int getSampleFlags(){return sample()?(int)info[2]:0;}public long getSampleSize(){return sample()?data().length:-1;}
 public boolean advance(){if(!sample())return false;current=false;sampleData=null;return sample();}
 public void seekTo(long timeUs,int mode){ready();if(timeUs<0||mode<0||mode>2)throw new IllegalArgumentException();if(mode==2)throw new UnsupportedOperationException("Closest sync seek requires bidirectional keyframe indexing");MediaNative.seek(handle,timeUs,mode);current=false;eof=false;sampleData=null;}
 public void release(){if(handle!=0){MediaNative.close(handle,1);handle=0;}selected.clear();nalLengths.clear();current=false;sampleData=null;}
}
